    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 12000); // 10% of 120000
  assert.equal(totals.total, 108000); // 120000 - 12000
});

test('invoiceTotals calculates discount correctly with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 2, discountPercent: 5 },
    ],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 120000 + 17000); // 137000
  assert.equal(totals.discount, 12000 + 850); // 12850
  assert.equal(totals.total, 124150); // 137000 - 12850
});

test('invoiceTotals clamps total at 0 if discount exceeds subtotal', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'LOGO-PACK', qty: 1, name: 'Logo package', unitPrice: 100, vatRate: 21, discountPercent: 100 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100);
  assert.equal(totals.discount, 100);
  assert.equal(totals.total, 0);
});

test('addLine accepts and stores discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const r2 = addLine(invoice, { sku: 'DES-HOUR', qty: 1, discountPercent: 15 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 15);
});

test('addLine defaults discountPercent to 0 if not provided', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const r2 = addLine(invoice, { sku: 'DES-HOUR', qty: 1 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 0);
});

test('addLine preserves discountPercent when increasing qty on existing line', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const r2 = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[0].qty, 2);
  assert.equal(r2.value.lines[0].discountPercent, 10);
});

test('addLine updates discountPercent when provided on existing line', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const r2 = addLine(invoice, { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[0].qty, 2);
  assert.equal(r2.value.lines[0].discountPercent, 20);
});

test('addLine rejects invalid discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  assert.deepEqual(addLine(invoice, { sku: 'DES-HOUR', qty: 1, discountPercent: 150 }), { ok: false, error: 'DISCOUNT_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'DES-HOUR', qty: 1, discountPercent: -1 }), { ok: false, error: 'DISCOUNT_INVALID' });
});

